import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate(
        [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    ) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_once():
    groups = {
        "large": [{"flagged": True}, {"flagged": True}, {"flagged": False}],
        "small": [{"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_transcript_log_fields_and_skipped_lines():
    assert parse_transcript_log([
        "  # a comment\n",
        "   \n",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,2", "x,2,1,extra", "x,nope,1"])
def test_parse_transcript_log_errors_have_original_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# skipped", line])


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "a", "day": 5, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 1, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range_and_outside_records_ignored():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 5, 3) == []


def test_monitor_summary_specification():
    groups = {
        "a": [
            {"id": "1", "day": 1, "flagged": True},
            {"id": "2", "day": 2, "flagged": False},
        ],
        "empty": [],
        "b": [{"id": "3", "day": 3, "flagged": True}],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "a": [{"flagged": True}],
        "b": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]


def test_flag_rate_by_group_returns_sorted_keys_and_none_for_empty():
    assert flag_rate_by_group({"z": [], "a": [{"flagged": None}]}) == {
        "a": 0.0,
        "z": None,
    }


def test_longest_flag_streak_counts_positive_runs():
    assert longest_flag_streak([1, 2, 0, -1, 3, 4, 5]) == 3
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, -1]) == 0

